// 同步源码到 quick-compile 产物：每个模块的 dst 文件 + __qc_bundle__.js // 用法: node sync_bundle.js const fs = require('fs'); const path = require('path');  const CLIENT = 'd:\\babykylin_scmj\\client'; const SRC = path.join(CLIENT, 'assets\\module\\mjgame\\scripts'); const SRC_RES = path.join(CLIENT, 'assets\\resources\\script'); const DST = path.join(CLIENT, 'temp\\quick-scripts\\dst\\assets\\module\\mjgame\\scripts'); const DST_RES = path.join(CLIENT, 'temp\\quick-scripts\\dst\\assets\\resources\\script'); const BUNDLE = path.join(CLIENT, 'temp\\quick-scripts\\dst\\__qc_bundle__.js');  // 需要同步的模块：[源文件名, dst文件名, 模块UUID, 模块显示名] const MODULES = [     { file: 'MJGameLDH.js', uuid: '85c5aNOTWNCFrgpYPdauSJ3', name: 'MJGameLDH' },     { file: 'MJGameFCS.js', uuid: '5930bY4N6ND+ZJVP1BXpwFG', name: 'MJGameFCS' },     { file: 'MJRoom.js',    uuid: '9f0aeRoHPlBlp2qaYLq2unR', name: 'MJRoom' },     { file: 'PengGangs.js', uuid: '594e6upScRAKqdCYJ7LQDR6', name: 'PengGangs' },     { file: 'Folds.js',     uuid: '9a304jWq+JBAIkQm1bY2h61', name: 'Folds' },     { file: 'GameOver.js',  uuid: 'ce353SCfT5DTo9QXPqOipBU', name: 'GameOver' },     { file: 'GameNetMgr.js', uuid: '4c5cfC0K1VGQYg9AqndkIE9', name: 'GameNetMgr', srcDir: SRC_RES, dstDir: DST_RES }, ];  function rebuildDstModule(mod) {     const srcPath = path.join(mod.srcDir || SRC, mod.file);     const dstPath = path.join(mod.dstDir || DST, mod.file);     const src = fs.readFileSync(srcPath, 'utf8');     const dst = fs.readFileSync(dstPath, 'utf8');      const pushMarker = `cc._RF.push(module, '${mod.uuid}', '${mod.name}');`;     const pushIdx = dst.indexOf(pushMarker);     if (pushIdx < 0) throw new Error(`push marker not found in ${mod.file}`);     const header = dst.slice(0, pushIdx + pushMarker.length);      const popMarker = 'cc._RF.pop();';     const popIdx = dst.lastIndexOf(popMarker);     if (popIdx < 0) throw new Error(`pop marker not found in ${mod.file}`);     const footer = dst.slice(popIdx);      const newBody =         `\n// module/mjgame/scripts/${mod.file}\n\n` +         `"use strict";\n` +         src.replace(/\r\n/g, '\n');      const out = header + newBody + '\n' + footer;     fs.writeFileSync(dstPath, out, 'utf8');     console.log(`[dst] ${mod.file} -> ${dstPath} (${out.length} bytes)`);     return out; }  function updateBundle(mod, newModuleContent) {     const bundle = fs.readFileSync(BUNDLE, 'utf8');     // bundle 中每个模块块与 dst 文件内容一致     const oldDst = fs.readFileSync(path.join(mod.dstDir || DST, mod.file), 'utf8');     // 用新内容替换 bundle 中旧的模块内容     if (bundle.indexOf(oldDst) < 0) {         // 可能旧 dst 与 bundle 中不一致，尝试按 push/pop 标记定位         const pushMarker = `cc._RF.push(module, '${mod.uuid}', '${mod.name}');`;         const bPush = bundle.indexOf(pushMarker);         if (bPush < 0) throw new Error(`bundle push marker not found for ${mod.file}`);         // 找到该模块块起始：回溯到 (function() {         const blockStart = bundle.lastIndexOf('(function() {', bPush);         if (blockStart < 0) throw new Error(`block start not found for ${mod.file}`);         // 找到该模块块结束：下一个 })();         const afterPush = bundle.indexOf('cc._RF.pop();', bPush);         const blockEnd = bundle.indexOf('})();', afterPush);         if (blockEnd < 0) throw new Error(`block end not found for ${mod.file}`);         const blockEndFull = blockEnd + 5;         const before = bundle.slice(0, blockStart);         const after = bundle.slice(blockEndFull);         // 新模块块 = newModuleContent (它本身就是完整的 (function(){...})(); 块)         const newBundle = before + newModuleContent + after;         fs.writeFileSync(BUNDLE, newBundle, 'utf8');         console.log(`[bundle] ${mod.file} replaced (${newBundle.length} bytes)`);     } else {         const newBundle = bundle.split(oldDst).join(newModuleContent);         fs.writeFileSync(BUNDLE, newBundle, 'utf8');         console.log(`[bundle] ${mod.file} replaced via split (${newBundle.length} bytes)`);     } }  for (const mod of MODULES) {     const content = rebuildDstModule(mod);     updateBundle(mod, content); } console.log('SYNC DONE');